1. use std::sync::Once;
2. 
3. use indoc::indoc;
4. use pretty_assertions::assert_str_eq;
5. 
6. use liwe::model::config::MarkdownOptions;
7. use liwe::{
8.     graph::Graph,
9.     state::{from_indoc, to_indoc},
10. };
11. 
12. static INIT: Once = Once::new();
13. 
14. fn setup() {
15.     INIT.call_once(|| {
16.         env_logger::builder().init();
17.     });
18. }
19. 
20. fn bare_options() -> MarkdownOptions {
21.     MarkdownOptions {
22.         bare_frontmatter: true,
23.         ..Default::default()
24.     }
25. }
26. 
27. #[test]
28. fn reader_detects_bare_title_block() {
29.     setup();
30. 
31.     let graph = Graph::import(
32.         &from_indoc(indoc! {"
33.             title: Foo
34.             status: ready
35. 
36.             # Body
37.             "}),
38.         bare_options(),
39.         None,
40.     );
41. 
42.     let state = graph.export();
43.     let content = state.values().next().unwrap();
44.     // The metadata should have been parsed — the output should have fenced front matter
45.     // since we're exporting with bare_frontmatter=true, it should be bare again
46.     assert!(content.starts_with("title: Foo"));
47. }
48. 
49. #[test]
50. fn reader_skips_when_disabled() {
51.     setup();
52. 
53.     let graph = Graph::import(
54.         &from_indoc(indoc! {"
55.             title: Foo
56.             status: ready
57. 
58.             # Body
59.             "}),
60.         MarkdownOptions::default(), // bare_frontmatter = false
61.         None,
62.     );
63. 
64.     let state = graph.export();
65.     let content = state.values().next().unwrap();
66.     // Without bare_frontmatter, "title: Foo" is just body text, no metadata parsed
67.     // So no frontmatter block in output
68.     assert!(!content.contains("---"));
69. }
70. 
71. #[test]
72. fn reader_skips_when_no_title_first_line() {
73.     setup();
74. 
75.     let graph = Graph::import(
76.         &from_indoc(indoc! {"
77.             date: 2024-01-01
78.             title: Foo
79. 
80.             # Body
81.             "}),
82.         bare_options(),
83.         None,
84.     );
85. 
86.     let state = graph.export();
87.     let content = state.values().next().unwrap();
88.     // First line isn't "title: " so no metadata parsed
89.     assert!(!content.contains("---"));
90. }
91. 
92. #[test]
93. fn reader_does_not_misparse_prose() {
94.     setup();
95. 
96.     let graph = Graph::import(
97.         &from_indoc(indoc! {"
98.             This is a paragraph.
99. 
100.             # H
101.             "}),
102.         bare_options(),
103.         None,
104.     );
105. 
106.     let state = graph.export();
107.     let content = state.values().next().unwrap();
108.     assert!(!content.contains("---"));
109. }
110. 
111. #[test]
112. fn reader_still_handles_fenced() {
113.     setup();
114. 
115.     let graph = Graph::import(
116.         &from_indoc(indoc! {"
117.             ---
118.             title: Fenced
119.             ---
120. 
121.             # Header
122.             "}),
123.         bare_options(),
124.         None,
125.     );
126. 
127.     let state = graph.export();
128.     let content = state.values().next().unwrap();
129.     // With bare_frontmatter enabled, writer should emit bare format
130.     assert!(content.starts_with("title: Fenced"));
131.     assert!(!content.starts_with("---"));
132. }
133. 
134. #[test]
135. fn writer_emits_bare_when_enabled() {
136.     setup();
137. 
138.     let input = indoc! {"
139.         title: Foo
140. 
141.         # Body
142.     "};
143. 
144.     let graph = Graph::import(
145.         &from_indoc(input),
146.         bare_options(),
147.         None,
148.     );
149. 
150.     let state = graph.export();
151.     let content = state.values().next().unwrap();
152.     assert!(content.starts_with("title: Foo"));
153.     assert!(!content.starts_with("---"));
154.     assert!(content.contains("# Body"));
155. }
156. 
157. #[test]
158. fn writer_emits_fenced_when_disabled() {
159.     setup();
160. 
161.     let graph = Graph::import(
162.         &from_indoc(indoc! {"
163.             ---
164.             title: Foo
165.             ---
166. 
167.             # Body
168.             "}),
169.         MarkdownOptions::default(),
170.         None,
171.     );
172. 
173.     let state = graph.export();
174.     let content = state.values().next().unwrap();
175.     assert!(content.starts_with("---\ntitle: Foo\n---"));
176. }
