         let generated_index = parent.join(format!("_{}.md", dir_name));

         // If user index exists, delete generated if present, skip.
         if user_index.exists() {
             if generated_index.exists() {
                 let _ = fs::remove_file(&generated_index);
             }
             continue;
         }

         // Collect children: .md files directly in dir (excluding _*.md generated indices)
         // and subdirectories that are in dirs_with_md.
         let mut children_keys: BTreeSet<String> = BTreeSet::new();

         let relative_dir = dir.strip_prefix(base_path).unwrap_or(Path::new(""));

         // Direct .md files in this directory
         if let Ok(entries) = fs::read_dir(dir) {
             for entry in entries.flatten() {
                 let p = entry.path();
                 if p.is_file() && p.extension().is_some_and(|ext| ext == "md") {
                     let fname = p
                         .file_name()
                         .map(|n| n.to_string_lossy().to_string())
                         .unwrap_or_default();
                     // Skip generated index files
                     if fname.starts_with('_') {
                         continue;
                     }
                     let key_name = fname.trim_end_matches(".md");
                     let child_key = format!(
                         "{}/{}",
                         relative_dir.to_string_lossy(),
                         key_name
                     );
                     children_keys.insert(child_key);
                 } else if p.is_dir() && dirs_with_md.contains(&p) {
                     let subdir_name = p
                         .file_name()
                         .map(|n| n.to_string_lossy().to_string())
                         .unwrap_or_default();
                     let child_key = format!(
                         "{}/{}",
                         relative_dir.to_string_lossy(),
                         subdir_name
                     );
                     children_keys.insert(child_key);
                 }
             }
         }

         if children_keys.is_empty() {
             continue;
         }

         // Generate content
         let mut content = format!("# {}\n", dir_name);
         for child_key in &children_keys {
             let link_text = child_key.rsplit('/').next().unwrap_or(child_key);
             content.push_str(&format!("\n[{}]({})\n", link_text, child_key));
         }

         // Check if regeneration needed
         if generated_index.exists() {
             if let Ok(existing) = fs::read_to_string(&generated_index) {
                 if existing == content {
                     continue; // up to date
                 }
             }
         }

         let _ = fs::write(&generated_index, &content);
     }
